import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv2d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <ATen/cuda/CUDAContext.h>

#define TILE_W 32
#define TILE_H 16
#define MAX_OC_TILE 4
#define THREAD_X_TILE 4
__global__ void conv2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C_in, int H, int W,
    int C_out, int K,
    int stride, int padding, int dilation,
    int groups,
    int H_out, int W_out,
    int in_tile_h, int in_tile_w,
    int oc_tile)
{
    extern __shared__ float shmem[];
    int out_x_base = blockIdx.x * TILE_W + threadIdx.x * THREAD_X_TILE;
    int out_y = blockIdx.y * blockDim.y + threadIdx.y;
    int groups_per_batch = C_out / oc_tile;
    int bc = blockIdx.z;
    int n = bc / groups_per_batch;
    int oc_tile_idx = bc % groups_per_batch;
    int oc_base = oc_tile_idx * oc_tile;
    int C_in_per_group = C_in / groups;
    int C_out_per_group = C_out / groups;
    int group_id = oc_base / C_out_per_group;
    float sum[MAX_OC_TILE][THREAD_X_TILE];
    #pragma unroll
    for (int t = 0; t < MAX_OC_TILE; ++t) {
        #pragma unroll
        for (int tt = 0; tt < THREAD_X_TILE; ++tt) sum[t][tt] = 0.0f;
    }
    int in_x0 = blockIdx.x * TILE_W * stride - padding;
    int in_y0 = blockIdx.y * blockDim.y * stride - padding;
    int tile_size = in_tile_h * in_tile_w;
    float* s_weight = shmem + tile_size;
    int tid = threadIdx.y * blockDim.x + threadIdx.x;
    int nthreads = blockDim.x * blockDim.y;
    for (int ic = 0; ic < C_in_per_group; ++ic) {
        int input_channel = group_id * C_in_per_group + ic;
        for (int idx = tid; idx < tile_size; idx += nthreads) {
            int ty = idx / in_tile_w;
            int tx = idx % in_tile_w;
            int in_y = in_y0 + ty;
            int in_x = in_x0 + tx;
            float val = 0.0f;
            if (in_y >= 0 && in_y < H && in_x >= 0 && in_x < W) {
                val = input[((n * C_in + input_channel) * H + in_y) * W + in_x];
            }
            shmem[idx] = val;
        }
        int weight_count = oc_tile * K * K;
        for (int widx = tid; widx < weight_count; widx += nthreads) {
            int t = widx / (K * K);
            int kk = widx % (K * K);
            int oc = oc_base + t;
            s_weight[widx] = weight[((oc * C_in_per_group + ic) * K) * K + kk];
        }
        __syncthreads();
        if (out_y < H_out) {
            int local_y0 = threadIdx.y * stride;
            #pragma unroll
            for (int t = 0; t < oc_tile; ++t) {
                const float* w_ptr = s_weight + t * K * K;
                #pragma unroll
                for (int tt = 0; tt < THREAD_X_TILE; ++tt) {
                    int out_x = out_x_base + tt;
                    if (out_x < W_out) {
                        int local_x0 = (threadIdx.x * THREAD_X_TILE + tt) * stride;
                        float partial = 0.0f;
                        #pragma unroll
                        for (int ky = 0; ky < K; ++ky) {
                            #pragma unroll
                            for (int kx = 0; kx < K; ++kx) {
                                int sy = local_y0 + ky * dilation;
                                int sx = local_x0 + kx * dilation;
                                partial += shmem[sy * in_tile_w + sx] * w_ptr[ky * K + kx];
                            }
                        }
                        sum[t][tt] += partial;
                    }
                }
            }
        }
        __syncthreads();
    }
    if (out_y < H_out) {
        #pragma unroll
        for (int t = 0; t < oc_tile; ++t) {
            int oc = oc_base + t;
            float bval = (bias != nullptr) ? bias[oc] : 0.0f;
            #pragma unroll
            for (int tt = 0; tt < THREAD_X_TILE; ++tt) {
                int out_x = out_x_base + tt;
                if (out_x < W_out) {
                    output[((n * C_out + oc) * H_out + out_y) * W_out + out_x] = sum[t][tt] + bval;
                }
            }
        }
    }
}
torch::Tensor conv2d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation,
    int groups)
{
    input = input.contiguous();
    weight = weight.contiguous();
    int N = input.size(0);
    int C_in = input.size(1);
    int H = input.size(2);
    int W = input.size(3);
    int C_out = weight.size(0);
    int K = weight.size(2);
    int H_out = (H + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
    int W_out = (W + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
    auto output = torch::empty({N, C_out, H_out, W_out}, input.options());
    int C_out_per_group = C_out / groups;
    int oc_tile = 1;
    if (C_out_per_group % 4 == 0) {
        oc_tile = 4;
    } else if (C_out_per_group % 2 == 0) {
        oc_tile = 2;
    } else {
        oc_tile = 1;
    }
    dim3 block(TILE_W / THREAD_X_TILE, TILE_H);
    dim3 grid((W_out + TILE_W - 1) / TILE_W,
              (H_out + TILE_H - 1) / TILE_H,
              N * (C_out / oc_tile));
    int in_tile_h = (TILE_H - 1) * stride + (K - 1) * dilation + 1;
    int in_tile_w = (TILE_W - 1) * stride + (K - 1) * dilation + 1;
    size_t shmem_size = (size_t)in_tile_h * in_tile_w * sizeof(float) + (size_t)oc_tile * K * K * sizeof(float);
    const float* bias_ptr = nullptr;
    torch::Tensor bias_c;
    if (bias.defined() && bias.numel() > 0) {
        bias_c = bias.contiguous();
        bias_ptr = bias_c.data_ptr<float>();
    }
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    conv2d_kernel<<<grid, block, shmem_size, stream>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        N, C_in, H, W,
        C_out, K,
        stride, padding, dilation,
        groups,
        H_out, W_out,
        in_tile_h, in_tile_w,
        oc_tile
    );
    return output;
}
"""

conv2d_header = r"""
torch::Tensor conv2d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation,
    int groups);
"""

conv2d_module = load_inline(
    name="custom_conv2d",
    cpp_sources=conv2d_header,
    cuda_sources=conv2d_source,
    functions=["conv2d_forward"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Custom CUDA implementation of a standard 2D convolution with asymmetric
    input and a square kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        # Reuse nn.Conv2d only to hold/initialize parameters identically to the reference model.
        self.conv2d = nn.Conv2d(in_channels, out_channels, (kernel_size, kernel_size),
                                 stride=stride, padding=padding, dilation=dilation,
                                 groups=groups, bias=bias)
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.cuda().contiguous()
        weight = self.conv2d.weight
        if self.conv2d.bias is not None:
            bias = self.conv2d.bias
        else:
            bias = torch.Tensor().to(x.device)

        return conv2d_module.conv2d_forward(
            x, weight, bias,
            self.stride, self.padding, self.dilation, self.groups
        )


